package com.shopsphere.controller;
import com.shopsphere.model.User; import com.shopsphere.util.DB; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.ServletException; import java.io.IOException; import java.sql.*;
@WebServlet("/cart")
public class CartServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{try{User u=(User)q.getSession().getAttribute("user");try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("SELECT p.product_id,p.name,p.price,p.discount,p.image_url,c.quantity,(p.price*(1-p.discount/100))*c.quantity line_total FROM cart c JOIN products p ON p.product_id=c.product_id WHERE c.user_id=?")){s.setInt(1,u.getUserId());try(ResultSet rs=s.executeQuery()){var items=new java.util.ArrayList<java.util.Map<String,Object>>();while(rs.next()){var m=new java.util.HashMap<String,Object>();m.put("id",rs.getInt("product_id"));m.put("name",rs.getString("name"));m.put("price",rs.getBigDecimal("price"));m.put("discount",rs.getBigDecimal("discount"));m.put("imageUrl",rs.getString("image_url"));m.put("quantity",rs.getInt("quantity"));m.put("lineTotal",rs.getBigDecimal("line_total"));items.add(m);}q.setAttribute("items",items);}}q.getRequestDispatcher("/WEB-INF/views/cart.jsp").forward(q,r);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{try{User u=(User)q.getSession().getAttribute("user");int id=Integer.parseInt(q.getParameter("productId"));int qty=Math.max(1,Math.min(20,Integer.parseInt(q.getParameter("quantity")==null?"1":q.getParameter("quantity"))));try(Connection c=DB.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO cart(user_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=LEAST(quantity+VALUES(quantity),20)")){s.setInt(1,u.getUserId());s.setInt(2,id);s.setInt(3,qty);s.executeUpdate();}r.sendRedirect(q.getContextPath()+"/cart");}catch(Exception e){throw new ServletException(e);}}
}
